function lintURL(raw){var signal=[],hostname="",isInvalid=false;if(!raw.trim())return {signal:signal,hostname:"",invalid:false};
var entry=raw.trim();
if(entry.length>2048){return {signal:[{id:"url-long",title:"Unusually long link",level:"medium",reason:"Long links can conceal the part that controls the true destination.",step:"Do not open the link until you can verify its actual destination."}],hostname:"",invalid:false};}
try{
 var provided=/^[a-zA-Z][a-zA-Z\d+.-]*:/.test(entry)?entry:"https://"+entry;
 var parsed=new URL(provided);
 if(!/^https?:$/.test(parsed.protocol)||!parsed.hostname){throw new Error("invalid");}
 hostname=parsed.hostname.toLowerCase();
 if(parsed.username||parsed.password){signal.push({id:"url-user",level:"critical",title:"Misleading address with an @ sign",reason:"The name before @ may appear to be a trusted brand, but the real destination is the hostname after @.",step:"Do not sign in or pay through that link. Find the genuine website yourself."});}
 if(parsed.protocol==="http:"){signal.push({id:"url-http",level:"medium",title:"Website does not use HTTPS",reason:"This URL uses unencrypted HTTP. Even HTTPS would not prove a store or person is legitimate.",step:"Avoid entering payment or identity details on unsecured pages."});}
 if(hostname.includes("xn--")){signal.push({id:"url-punycode",level:"high",title:"Internationalised/punycode hostname",reason:"Some internationalised names are legitimate, but deceptive lookalike domains can use similar-looking characters.",step:"Check the exact destination against the official organisation's address."});}
 if(/^\d{1,3}(?:\.\d{1,3}){3}$/.test(hostname)){signal.push({id:"url-ip",level:"medium",title:"Direct IP address used as website",reason:"A raw IP address hides the familiar company domain that users might expect.",step:"Confirm the organisation's official website independently."});}
 var shorteners=["bit.ly","tinyurl.com","t.co","is.gd","cutt.ly","rb.gy","shorturl.at","tiny.cc","ow.ly"];
 if(shorteners.indexOf(hostname)>=0){signal.push({id:"url-short",level:"medium",title:"Shortened destination link",reason:"A link shortener conceals the final destination until followed.",step:"Ask for the official, full website address and verify it yourself."});}
 if(/\.(?:top|click|zip|rest|buzz|work)$/i.test(hostname)){signal.push({id:"url-tld",level:"info",title:"Unfamiliar website ending",reason:"Some legitimate websites use this domain ending; it is only a weak context signal, not proof of fraud.",step:"Verify the seller or organisation and check independent reviews."});}
 if(hostname.split(".").length>4){signal.push({id:"url-sub",level:"info",title:"Long chain of subdomains",reason:"Multiple subdomains can make a link difficult to interpret; the rightmost registered domain controls the site.",step:"Inspect the actual domain carefully before opening the page."});}
 var official={"paypal":"paypal.com","amazon":"amazon.com","google":"google.com","apple":"apple.com","microsoft":"microsoft.com","instagram":"instagram.com","whatsapp":"whatsapp.com"};
 for(var brand in official){if(!Object.prototype.hasOwnProperty.call(official,brand))continue;var officialDomain=official[brand];if(hostname.includes(brand) && hostname!==officialDomain&&!hostname.endsWith("."+officialDomain)){signal.push({id:"url-brand-"+brand,level:"medium",title:"Brand name appears in an unrelated domain",reason:"The link contains "+titleCase(brand)+" but is not under its standard primary domain. Legitimate third-party sites can also mention brands.",step:"Open the organisation's verified website by typing the known address yourself."});break;}}
 }catch(e){isInvalid=true;signal.push({id:"url-invalid",level:"info",title:"Link format cannot be checked",reason:"The entered text is not a valid HTTP(S) website address. This does not establish whether a claim is safe.",step:"Ask for the complete official link, but do not follow an unverified request."});}
 return {signal:signal,hostname:hostname,invalid:isInvalid};
}
function analyze(input){
 var message=String(input.message||"").slice(0,12000),link=String(input.link||"").slice(0,2048);
 var found=[],seen={};function add(s){if(seen[s.id])return;seen[s.id]=true;found.push(s);}
 RULES.forEach(function(r){if(r.cats!=="all"&&r.cats!==input.category)return;if(r.re.test(message+" "+link)){add({id:r.id,title:r.title,level:r.level,reason:r.reason,step:r.step});}});
 var analyzedURL=lintURL(link);analyzedURL.signal.forEach(add);
 (input.flags||[]).forEach(function(f){var rule=MANUAL[f];if(rule)add({id:"manual-"+f,title:rule.title,level:rule.level,reason:rule.reason,step:rule.step});});
 found.sort(function(a,b){return strength[b.level]-strength[a.level];});
 var countHigh=found.filter(function(s){return s.level==="critical"||s.level==="high";}).length,score=found.reduce(function(acc,s){return acc+strength[s.level];},0);
 var level=score>=50?"urgent":score>=16?"caution":"unknown";
 return {id:id(),date:new Date().toISOString(),category:input.category,hostname:analyzedURL.hostname,signals:found,level:level,score:score,high:countHigh,hasInput:!!(message.trim()||link.trim()||(input.flags||[]).length)};
}
function getAdvice(category){return {
 shopping:["Compare the exact domain with the retailer's official site","Look up independent reviews and refund terms","Prefer platforms and payment methods with buyer protections"],
 jobs:["Find the vacancy on the employer's official careers site","Verify recruiter identity using a published company number","Never pay to get a job or unlock supposed earnings"],
 investments:["Check the firm with the official financial regulator","Treat guaranteed returns or withdrawal fees as serious warnings","Don't trust screenshots, group testimonials or stranger recommendations"],
 rentals:["Verify ownership or agent credentials independently","Arrange a genuine viewing before paying","Do not send sensitive documents to unverified contacts"],
 identity:["Never share OTPs, passwords, seed phrases or remote access","Find the organisation's number separately, not in the message","If credentials were shared, change them and enable multifactor authentication"]
 }[category]||[];}
